class Solution:
    def rearrangeArray(self, nums: list[int]) -> list[int]:
        pos = [x for x in nums if x > 0]
        neg = [x for x in nums if x < 0]
        result = [0] * len(nums)
        for i in range(len(pos)):
            result[2 * i] = pos[i]
            result[2 * i + 1] = neg[i]
        return result

